// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.selfmodify/** * NOUS — Stored JavaScript skill script (Module 15 — Self-modify). * * Data model for a single self-modifying JS skill persisted by * [SelfModifyEngine]. Each skill is identified by a unique [name] (which is * also its skill ID in Brain's SkillRouter) and carries its full [script] * source plus metadata for versioning and audit. * * Storage: in-memory by default (in [SelfModifyEngine]). Production builds * should swap in a Room+SQLCipher-backed implementation that survives app * reinstalls (per ADR 0008's "no data loss on flavor switch" requirement). * * Versioning: [version] increments on every [SelfModifyEngine.updateSkill] * call. Callers can detect drift between their cached copy and the engine's * copy by comparing versions. The LLM self-correction loop reads this to * decide whether to regenerate a skill. * * @see SelfModifyEngine * @see <a href="docs/adr/0008-self-modifying-js-flavor-gated.md">ADR 0008</a> */data class SkillScript(    /** Unique skill identifier. Matches Brain's `BrainSkill.id`. */    val name: String,    /** Full JavaScript source. Passed verbatim to [RhinoJsSandbox.execute]. */    val script: String,    /** Epoch-millis creation timestamp. */    val createdAt: Long,    /** Epoch-millis last-update timestamp. Equal to [createdAt] if never updated. */    val updatedAt: Long,    /** Monotonically increasing version number, starting at 1. */    val version: Int,) {    init {        require(name.isNotBlank()) { "SkillScript.name must not be blank" }        require(version >= 1) { "SkillScript.version must be >= 1 (got $version)" }        require(createdAt >= 0) { "SkillScript.createdAt must be >= 0" }        require(updatedAt >= createdAt) {            "SkillScript.updatedAt ($updatedAt) must be >= createdAt ($createdAt)"        }    }    companion object {        /**         * Create a new [SkillScript] at the current wall-clock time.         *         * Used by [SelfModifyEngine.createSkill] — sets `createdAt` =         * `updatedAt` = now, `version` = 1.         *         * @param name unique skill ID.         * @param script full JS source.         * @param now epoch-millis (overrideable for tests; defaults to         *   `System.currentTimeMillis()`).         */        fun fresh(            name: String,            script: String,            now: Long = System.currentTimeMillis(),        ): SkillScript = SkillScript(            name = name,            script = script,            createdAt = now,            updatedAt = now,            version = 1,        )    }    /**     * Return a new [SkillScript] with [script] replaced, [updatedAt] set to     * [now], and [version] incremented by 1.     *     * Used by [SelfModifyEngine.updateSkill] — does NOT mutate this instance.     */    fun withUpdatedScript(        newScript: String,        now: Long = System.currentTimeMillis(),    ): SkillScript = copy(        script = newScript,        updatedAt = now,        version = version + 1,    )}